#!/usr/bin/env node
// Verifies this project's copy of the shared Claude standard against .claude/standard.lock.json.
// The copies are generated by claude-config/standard/sync.mjs: edit the source in claude-config and
// re-sync, never the copy. Exit 1 lists every copy that was edited, deleted or left behind.
// A project with a deploy.config.mjs is also held to the deploy standard (docs/deploy-standard-design.md): the config is valid,
// <siteRoot>/version.json is a valid release file, every stamped copy mirrors it (and a service worker names its cache from
// it), and the live docs hand nobody a deploy command the project refuses.
// Usage: node .claude/standard/verify.mjs [projectDir]   (vendored file: do not edit here)
import { createHash } from 'node:crypto';
import { existsSync, readFileSync, realpathSync } from 'node:fs';
import { join, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';

export const LOCK_PATH = '.claude/standard.lock.json';
export const DEPLOY_CONFIG = 'deploy.config.mjs';
const ONLY_LIST = /--only[\s=]+["']?([^\s`'"|)]+)/g;
// Only a deploy command is held to the `--only` vocabulary: `firebase emulators:start --only firestore,auth` is a different command.
const DEPLOY_COMMAND = /\bfirebase deploy\b|\bnpm run deploy\b/;
const NPM_RUN = /\bnpm run ([A-Za-z0-9:_-]+)/g;
// A line that names the bare form to warn against it ("bare" is the reliable marker); no instruction to USE it says so.
const IS_WARNING = /\bbare\b|never|wrong|aborts|instead of|rather than/i;

export function hashFile(absPath) {
  return createHash('sha256').update(readFileSync(absPath)).digest('hex');
}

export function readLock(projectDir) {
  const lockAbs = join(projectDir, LOCK_PATH);
  if (!existsSync(lockAbs)) return null;
  const lock = JSON.parse(readFileSync(lockAbs, 'utf8'));
  if (!lock || typeof lock.files !== 'object' || typeof lock.commit !== 'string') {
    throw new Error(`${LOCK_PATH} is malformed: expected { commit, kinds, files }`);
  }
  return lock;
}

/** Returns one problem string per vendored file that no longer matches its locked hash. */
export function findEditedCopies(projectDir, lock) {
  return Object.entries(lock.files).flatMap(([dest, hash]) => {
    const abs = join(projectDir, dest);
    if (!existsSync(abs)) return [`missing: ${dest}`];
    return hashFile(abs) === hash ? [] : [`edited: ${dest}`];
  });
}

const readJson = (file) => JSON.parse(readFileSync(file, 'utf8'));

/** Problems in the live docs: a bare `--only functions` in a deploy command (or a bare `hosting` where the project has no bare release), an npm script the project lacks. */
export function docsProblems(projectDir, config, scripts) {
  const bareHostingOk = 'hosting' in config.releases;
  return config.liveDocs.flatMap((doc) => {
    const file = join(projectDir, doc);
    if (!existsSync(file)) return []; // a doc may be renamed; the sweep list is not a manifest
    return readFileSync(file, 'utf8').split('\n').flatMap((line, i) => {
      const where = `${doc}:${i + 1}`;
      const bare = !DEPLOY_COMMAND.test(line) ? [] : [...line.matchAll(ONLY_LIST)].flatMap((m) => m[1].split(',')).filter((w) => w === 'functions' || (w === 'hosting' && !bareHostingOk));
      const bareProblem = IS_WARNING.test(line) ? [] : [...new Set(bare)].map((w) => `${where}: hands out a bare \`--only ${w}\`: ${line.trim()}`);
      const missing = [...line.matchAll(NPM_RUN)].map((m) => m[1]).filter((name) => !(name in scripts))
        .map((name) => `${where}: names \`npm run ${name}\`, which package.json does not define`);
      return [...bareProblem, ...missing];
    });
  });
}

/** The deploy standard's checks for a project that has a deploy.config.mjs; [] for one that does not. */
export async function deployProblems(projectDir) {
  if (!existsSync(join(projectDir, DEPLOY_CONFIG))) return [];
  let core;
  try {
    core = { config: await import('./deploy/config.mjs'), release: await import('./deploy/release-file.mjs') };
  } catch (error) {
    return [`${DEPLOY_CONFIG} exists but the deploy core (.claude/standard/deploy/) cannot be loaded: ${error.message}`];
  }
  let config;
  try {
    config = await core.config.loadConfig(projectDir, {
      repoBase: projectDir,
      firebaseJson: readJson(join(projectDir, 'firebase.json')),
      firebaserc: readJson(join(projectDir, '.firebaserc')),
      isCheckoutWithOrigin: () => true, // a sibling repo is not checked out in CI or a cloud session; the deploy itself checks it
    });
  } catch (error) { return [error.message]; }
  const own = Object.entries(config.releases).filter(([, line]) => line.repo === null);
  const mirror = own.flatMap(([key, line]) => core.release.mirrorProblems(projectDir, line, config.app ?? undefined).map((p) => `${key}: ${p}`));
  const scripts = existsSync(join(projectDir, 'package.json')) ? readJson(join(projectDir, 'package.json')).scripts ?? {} : {};
  return [...mirror, ...docsProblems(projectDir, config, scripts)];
}

function report(heading, problems) {
  console.error(`[standard] ${heading}`);
  problems.forEach((p) => console.error(`  ${p}`));
}

async function main() {
  const projectDir = resolve(process.argv[2] || process.cwd());
  const lock = readLock(projectDir);
  if (!lock) {
    console.error(`[standard] no ${LOCK_PATH} in ${projectDir}; run claude-config/standard/sync.mjs first.`);
    process.exit(1);
  }
  const problems = findEditedCopies(projectDir, lock);
  const deploy = await deployProblems(projectDir);
  if (problems.length > 0) {
    report(`${problems.length} vendored file(s) differ from claude-config ${lock.commit.slice(0, 8)}:`, problems);
    console.error('[standard] Make the change in claude-config, then run: node ~/.claude/standard/sync.mjs <project>');
  }
  if (deploy.length > 0) report(`${deploy.length} deploy problem(s) (${DEPLOY_CONFIG}):`, deploy);
  if (problems.length + deploy.length > 0) process.exit(1);
  console.log(`[standard] ${Object.keys(lock.files).length} files match claude-config ${lock.commit.slice(0, 8)}.`);
}

const isEntryPoint = process.argv[1] && realpathSync(process.argv[1]) === realpathSync(fileURLToPath(import.meta.url));
if (isEntryPoint) await main();
